// connect-runtime's write path end to end (spec 43.4 checks 4 to 6, 45.2, 45.3): REST writes
// against a fake CRM, operation by operation; SQL writes generated by the engine and run by a
// fake Silo Agent in one transaction of a throwaway customer database, each on the execution
// grant actions signs for exactly its statements (spec 10.4); the record reads around them;
// the gates before anything is sent.

import assert from 'node:assert/strict';
import { after, before, describe, test } from 'node:test';
import { createPrivateKey } from 'node:crypto';
import { prepareWrites, readRecords, writeRecords } from '../../src/contracts/connect-runtime/write.contract.ts';
import type { ServiceClient } from '../../src/infra/serviceClient.infra.ts';
import { createGrantSigner } from '../../src/services/actions/grants.service.ts';
import { inTx, uuidv7 } from '../db/harness.helper.ts';
import { TEST_GRANT_KEYS } from './connect.helper.ts';
import { createWritebackCell, type WritebackCell } from './writeback.helper.ts';

let wb: WritebackCell;
let actions: ServiceClient;
const signer = createGrantSigner(createPrivateKey(TEST_GRANT_KEYS.privateKey));

/** A write through the agent as actions makes it: prepared, signed for exactly its statements, then sent. */
async function signedWrite(body: { connectionId: string; object: string; operations: never[] | Record<string, unknown>[] }) {
  const prepared = await actions.call(prepareWrites, { body: body as never }, wb.cell.as(wb.root));
  assert.equal(prepared.grantRequired, true);
  const grant = signer.sign({
    organisationId: wb.cell.org, actionId: uuidv7(), actionKind: 'mutation', connectionId: body.connectionId, object: body.object,
    statements: prepared.statements!, payloadSha256: prepared.payloadSha256!,
  });
  return actions.call(writeRecords, { body: { ...body, grant } as never }, wb.cell.as(wb.root));
}

before(async () => {
  wb = await createWritebackCell();
  actions = wb.cell.client('actions');
});

after(async () => {
  await wb?.close();
});

describe('gates before anything is sent (spec 43.4)', () => {
  test('a connection that has not earned writes takes none', async () => {
    await assert.rejects(actions.call(writeRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', operations: [{ key: 'k1', operation: 'update_partial', identifier: 'c1', values: { score: 11 } }] },
    }, wb.cell.as(wb.root)), { code: 'write.not_enabled' });
    assert.equal(wb.contacts.get('c1')!.properties.score, 10);
  });

  test('only conformance writes in the sandbox', async () => {
    await assert.rejects(actions.call(writeRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', sandbox: true, operations: [{ key: 'k1', operation: 'delete', identifier: 'c1' }] },
    }, wb.cell.as(wb.root)), { code: 'write.sandbox_refused' });
  });

  test('the value check refuses the plan before any operation is sent', async () => {
    await wb.enableWrites(wb.restConnection);
    const before = wb.crmRequests.length;
    const out = await actions.call(writeRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', operations: [
        { key: 'a', operation: 'update_partial', identifier: 'c1', values: { score: 50 } },
        { key: 'b', operation: 'update_partial', identifier: 'c2', values: { score: 500 } },
      ] },
    }, wb.cell.as(wb.root));
    assert.deepEqual(out.results.map((r) => `${r.key}:${r.outcome}:${r.error?.meaning ?? ''}`), ['a:not_attempted:', 'b:failed:value_check']);
    assert.equal(wb.crmRequests.length, before, 'nothing was sent');
  });

  test('an undeclared field or operation is refused', async () => {
    await assert.rejects(actions.call(writeRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', operations: [{ key: 'a', operation: 'update_partial', identifier: 'c1', values: { nickname: 'x' } }] },
    }, wb.cell.as(wb.root)), { code: 'write.field_unknown' });
  });
});

describe('REST: each operation on its own (spec 45.2)', () => {
  test('update, create and delete, each reported; the created record\'s identifier comes back', async () => {
    const out = await actions.call(writeRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', operations: [
        { key: 'u', operation: 'update_partial', identifier: 'c3', values: { score: 33, name: 'Renamed person three' } },
        { key: 'c', operation: 'create', values: { email: 'new@example.com', name: 'New', score: 1 } },
        { key: 'd', operation: 'delete', identifier: 'c5' },
        { key: 'm', operation: 'update_partial', identifier: 'c999', values: { score: 1 } },
      ] },
    }, wb.cell.as(wb.root));
    assert.equal(out.transactional, false);
    const byKey = Object.fromEntries(out.results.map((r) => [r.key, r]));
    assert.equal(byKey['u']!.outcome, 'applied');
    assert.equal(byKey['c']!.outcome, 'applied');
    assert.match(byKey['c']!.identifier!, /^c\d+$/);
    assert.equal(byKey['d']!.outcome, 'applied');
    assert.deepEqual(byKey['m']!.error, { meaning: 'not_found', code: 'source.not_found' });
    assert.equal(wb.contacts.get('c3')!.properties.name, 'Renamed pers', 'the CRM truncated the name');
    assert.equal(wb.contacts.has('c5'), false);
    assert.equal(wb.contacts.get(byKey['c']!.identifier!)!.properties.email, 'new@example.com');
  });

  test('records are read by identifier; a missing one reads as absent', async () => {
    const out = await actions.call(readRecords, {
      body: { connectionId: wb.restConnection, object: 'contacts', identifiers: ['c3', 'c5'], fields: ['name', 'score'], reason: 'read_back' },
    }, wb.cell.as(wb.root));
    assert.deepEqual(out.records, [
      { identifier: 'c3', values: { id: 'c3', name: 'Renamed pers', score: 33 } },
      { identifier: 'c5', values: null },
    ]);
  });
});

describe('SQL: one transaction per plan (spec 45.2)', () => {
  test('a write through the agent without its grant, or with a grant for other statements, is refused before it leaves the cell', async () => {
    await wb.enableWrites(wb.sqlConnection);
    const plan = { connectionId: wb.sqlConnection, object: 'orders', operations: [{ key: 'u', operation: 'update_partial', identifier: '1', values: { status: 'lost' } }] };
    await assert.rejects(actions.call(writeRecords, { body: plan as never }, wb.cell.as(wb.root)), (e: { code?: string; details?: Record<string, unknown> }) => e.code === 'write.grant_refused' && e.details?.['reason'] === 'unsigned');
    const prepared = await actions.call(prepareWrites, { body: plan as never }, wb.cell.as(wb.root));
    const grant = signer.sign({
      organisationId: wb.cell.org, actionId: uuidv7(), actionKind: 'mutation', connectionId: wb.sqlConnection, object: 'orders',
      statements: 1, payloadSha256: prepared.payloadSha256!,
    });
    const other = { ...plan, operations: [{ ...plan.operations[0]!, values: { status: 'stolen' } }] };
    await assert.rejects(actions.call(writeRecords, { body: { ...other, grant } as never }, wb.cell.as(wb.root)),
      (e: { code?: string; details?: Record<string, unknown> }) => e.code === 'write.grant_refused' && e.details?.['reason'] === 'payload',
      'the grant covers exactly what was signed');
    const { rows } = await wb.customer.query('select status from sales.orders where id = 1');
    assert.notEqual(rows[0].status, 'stolen');
  });

  test('generated, parameterised statements commit together', async () => {
    await wb.enableWrites(wb.sqlConnection);
    const out = await signedWrite({ connectionId: wb.sqlConnection, object: 'orders', operations: [
      { key: 'u', operation: 'update_partial', identifier: '1', values: { status: 'shipped' } },
      { key: 'c', operation: 'create', values: { id: 11, customer: 'customer 11', status: 'open', amount: 110 } },
      { key: 'd', operation: 'delete', identifier: '10' },
    ] });
    assert.equal(out.transactional, true);
    assert.deepEqual(out.results.map((r) => `${r.key}:${r.outcome}:${r.identifier}`), ['u:applied:1', 'c:applied:11', 'd:applied:10']);
    const { rows } = await wb.customer.query('select id, status from sales.orders where id in (1, 10, 11) order by id');
    assert.deepEqual(rows, [{ id: 1, status: 'shipped' }, { id: 11, status: 'open' }]);
  });

  test('a statement that misses its record rolls the whole plan back', async () => {
    const out = await signedWrite({ connectionId: wb.sqlConnection, object: 'orders', operations: [
      { key: 'u', operation: 'update_partial', identifier: '2', values: { status: 'cancelled' } },
      { key: 'x', operation: 'update_partial', identifier: '999', values: { status: 'cancelled' } },
    ] });
    assert.deepEqual(out.results.map((r) => `${r.key}:${r.outcome}:${r.error?.meaning}`), ['u:failed:conflict', 'x:failed:not_found']);
    const { rows } = await wb.customer.query('select status from sales.orders where id = 2');
    assert.equal(rows[0].status, 'open', 'rolled back');
  });

  test('SQL records read back through the agent', async () => {
    const out = await actions.call(readRecords, {
      body: { connectionId: wb.sqlConnection, object: 'orders', identifiers: ['1', '10', '11'], fields: ['status'], reason: 'mutation' },
    }, wb.cell.as(wb.root));
    assert.deepEqual(out.records, [
      { identifier: '1', values: { id: 1, status: 'shipped' } },
      { identifier: '10', values: null },
      { identifier: '11', values: { id: 11, status: 'open' } },
    ]);
  });

  test('the secret was opened for mutation and read_back, and recorded', async () => {
    const { rows } = await inTx(wb.cell.credential, { orgId: wb.cell.org }, () => wb.cell.credential.query(
      `select distinct reason from iam.credential_unwraps where organisation_id = $1 and reason in ('mutation', 'read_back') order by reason`, [wb.cell.org]));
    assert.deepEqual(rows.map((r) => r.reason), ['mutation', 'read_back']);
  });
});

